def __getitem__(self, key, cache_getitem=Cache.__getitem__):
    value = cache_getitem(self, key)
    # Only touch the key if it's actually in the cache (might not be if
    # __missing__ returns a value without caching it)
    try:
        self.__touch(key)
    except KeyError:
        pass
    return value

